head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vScrenID = "ULDSTF05016.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_list_sync = function() {
    var url = "/SynthEtfTrctptInfo.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listSynthEtfIsu";
    url += "&inputMessageId=LISTSYNTHETFISU_INOUT&outputMessageId=LISTSYNTHETFISU_INOUT";
    url += "&ISU_KOR_NM=" + $c.stf.getObjectValue(txb_Search);
    dts.DataID = encodeURI(url);
    dts.reset();
};
scwin.txb_Search_onkeydown = function() {
    if (event.keyCode == 13) {
        scwin.fn_list_sync();
    }
};
scwin.dts_OnLoadError = function() {
    $c.stf.alert_error(dts);
};
scwin.dts_OnLoadCompleted = function(rowcount) {
    if (dts.errorMsg) {
        $c.win.alert(dts.errorMsg);
    } else {
        txb_TotCnt.setValue("총 " + rowcount + " 건");
    }
};
scwin.grd_IsuInst_OnDblClick = async function(row, colid) {
    var arrPar = new Array();
    if (scwin.fn_SetPar != undefined) {
        arrPar[0] = {
            ISU_CD: dts.getCellData(dts.getRowPosition(), "ISU_CD"),
            ISU_ENG_NM: dts.getCellData(dts.getRowPosition(), "ISU_ENG_NM")
        };
        scwin.fn_SetPar(arrPar);
    }
    await $c.frame.CloseFrame();
};
scwin.img_Search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.img_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    window.document.body.scroll = "no";
    var arrPar = new Array();
    var parentWin = $c.frame.path("../");
    scwin.fn_GetPar = parentWin.scwin.fn_GetPar;
    scwin.fn_SetPar = parentWin.scwin.fn_SetPar;
    if (scwin.fn_GetPar != undefined) {
        scwin.fn_GetPar(arrPar);
    }
    txb_Search.focus();
    scwin.fn_list_sync();
};
